import { access, mkdtemp, readdir, readFile, rename, rm, writeFile } from "node:fs/promises"
import path from "node:path"
import { fileURLToPath } from "node:url"

const projectRoot = fileURLToPath(new URL("..", import.meta.url))
const constDirectory = path.join(projectRoot, "const")
const blogDirectory = path.join(projectRoot, "const", "blog")
const registryPath = path.join(blogDirectory, "registry.generated.ts")
const SLUG_PATTERN = /^[a-z0-9]+(?:-[a-z0-9]+)*$/
const GENERATED_HEADER =
  "// This file is generated by scripts/generate-blog-registry.mjs. Do not edit.\n"
const GENERATED_TYPE_IMPORT =
  'import type { BlogArticleRegistryEntry } from "./types"\n'

async function exists(filePath) {
  try {
    await access(filePath)
    return true
  } catch {
    return false
  }
}

function createErrorRegistry(errors) {
  return `${GENERATED_HEADER}${GENERATED_TYPE_IMPORT}
export const BLOG_ARTICLE_ENTRIES = [] as const satisfies readonly BlogArticleRegistryEntry[]

throw new Error(${JSON.stringify(errors.join("\n"))})
`
}

function createRegistry(slugs) {
  const imports = slugs.flatMap((slug, index) => [
    `import { content as article${index}Content } from "./${slug}/content"`,
    `import { meta as article${index}Meta } from "./${slug}/meta"`,
  ])
  const entries = slugs.map(
    (slug, index) => `  {
    directorySlug: "${slug}",
    meta: article${index}Meta,
    content: article${index}Content,
  },`,
  )

  return `${GENERATED_HEADER}${GENERATED_TYPE_IMPORT}${imports.join("\n")}

export const BLOG_ARTICLE_ENTRIES = [
${entries.join("\n")}
] as const satisfies readonly BlogArticleRegistryEntry[]
`
}

async function writeIfChanged(content) {
  let currentContent
  try {
    currentContent = await readFile(registryPath, "utf8")
  } catch {
    currentContent = undefined
  }

  if (currentContent !== content) {
    const temporaryDirectory = await mkdtemp(path.join(constDirectory, ".blog-registry-"))
    const temporaryRegistryPath = path.join(temporaryDirectory, "registry.generated.ts")
    try {
      await writeFile(temporaryRegistryPath, content, "utf8")
      await rename(temporaryRegistryPath, registryPath)
    } finally {
      await rm(temporaryDirectory, { recursive: true, force: true })
    }
  }
}

export async function generateBlogRegistry() {
  const entries = await readdir(blogDirectory, { withFileTypes: true })
  const directories = entries.filter((entry) => entry.isDirectory())
  const errors = []
  const slugs = []

  for (const directory of directories.sort((a, b) => a.name.localeCompare(b.name))) {
    const slug = directory.name
    if (!SLUG_PATTERN.test(slug)) {
      errors.push(`Invalid blog article directory name: ${slug}`)
      continue
    }

    const hasMeta = await exists(path.join(blogDirectory, slug, "meta.ts"))
    const hasContent = await exists(path.join(blogDirectory, slug, "content.ts"))

    if (!hasMeta) errors.push(`Incomplete blog article "${slug}": meta.ts is missing.`)
    if (!hasContent) errors.push(`Incomplete blog article "${slug}": content.ts is missing.`)

    if (hasMeta && hasContent) slugs.push(slug)
  }

  await writeIfChanged(
    errors.length > 0 ? createErrorRegistry(errors) : createRegistry(slugs),
  )
}

const isDirectRun = process.argv[1] === fileURLToPath(import.meta.url)
if (isDirectRun) {
  await generateBlogRegistry()
}
